from abc import ABCMeta, abstractmethod
from future.utils import with_metaclass


class MovePolicy(with_metaclass(ABCMeta)):
    @abstractmethod
    def move(self, source_callbacks, target_callbacks):
        pass


class Forbidden(MovePolicy):
    def move(self, source_callbacks, target_callbacks):
        pass


class AlwaysMove(MovePolicy):
    def move(self, source_callbacks, target_callbacks):
        target_callbacks.extend(source_callbacks)
        del source_callbacks[:]
